--- css vars
/* Politize sua vizinhança. Folha escrita à mão. Mobile-first: a base é a tela de 360 px. */
*,*::before,*::after{box-sizing:border-box}
:root{
  --paper:#f7f5ee;--paper2:#efece2;--card:#ffffff;--ink:#151812;--ink2:#2a2f27;--muted:#535b54;--line:#d5d2c6;
  --verde:#0b7a3b;--verde-esc:#095f2e;--verde-claro:#0f9d58;--verde-txt:#0a6e35;
  --amarelo:#f2c230;--amarelo2:#ffcc29;--ouro-txt:#7d5b00;
  --azul:#0d2238;--azul2:#1f5f9e;--azul-txt:#1a5189;--azul3:#123150;
  --flavio:#1f5f9e;--lula:#c8412f;--lula-txt:#a8321f;--terceira:#0b7a3b;
  --display:Fraunces,Georgia,serif;--sans:"IBM Plex Sans Condensed",Arial,sans-serif;--mono:"IBM Plex Mono",ui-monospace,monospace;
  --wrap:min(1160px,calc(100% - 32px));--raio:14px;
}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:18px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.wrap{width:var(--wrap);margin:0 auto}
a{color:var(--azul-txt)}
a:hover{color:var(--azul)}
:focus-visible{outline:3px solid var(--amarelo2);outline-offset:2px;border-radius:4px}
.skip{position:absolute;left:-9999px}
.skip:focus{left:8px;top:8px;background:var(--ink);color:var(--paper);padding:10px 14px;z-index:99}
[hidden]{display:none!important}

/* ---------- hero: céu com as estrelas da bandeira e o losango ---------- */
.hero{position:relative;overflow:hidden;color:#f4f2ea;background:radial-gradient(120% 90% at 85% 0%,#1c3d63 0%,var(--azul) 55%,#0a1a2b 100%);padding:0 0 108px}
.hero-ceu{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.hero-ceu circle{fill:#fff}
.hero-losango{position:absolute;right:-180px;top:40px;width:520px;height:520px;transform:rotate(45deg) scaleX(.62) scaleY(1);border:2px solid rgb(242 194 48 / 38%);pointer-events:none}
.hero-losango::after{content:"";position:absolute;inset:34%;border-radius:50%;border:2px solid rgb(255 255 255 / 16%)}
.hero-in{position:relative;z-index:1}
.brand{display:flex;align-items:center;gap:10px;padding:22px 0 0;font-family:var(--mono);font-size:.74rem;letter-spacing:.13em;text-transform:uppercase;color:#c3ccd5}
.brand a{display:flex;align-items:center;gap:10px;color:inherit;text-decoration:none;min-height:44px}
.brand img{width:26px;height:26px;border-radius:4px}
.eyebrow{font-family:var(--mono);font-size:.76rem;letter-spacing:.14em;text-transform:uppercase;color:var(--amarelo2);margin:28px 0 0}
.hero h1{font-family:var(--display);font-weight:900;font-size:clamp(2.5rem,9.5vw,5.2rem);line-height:.95;letter-spacing:-.03em;margin:12px 0 0;max-width:15ch}
.hero h1 em{display:block;font-style:italic;font-weight:500;font-size:.42em;line-height:1.15;letter-spacing:-.01em;color:var(--amarelo2);margin-top:.5em;max-width:30ch}
.hero h1 em:empty{display:none}
.deck{max-width:62ch;color:#dfe5ea;font-size:1.08rem;margin:20px 0 0}
.deck:empty{display:none}
.hero-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px;margin:28px 0 0;max-width:720px}
.hero-stats:empty{display:none}
.hero-stats>div{border-top:3px solid var(--verde-claro);padding-top:8px}
.hero-stats>div:nth-child(2){border-top-color:var(--amarelo)}
.hero-stats>div:nth-child(3){border-top-color:#6f9fd8}
.hero-stats dt{font-family:var(--mono);font-size:.7rem;letter-spacing:.1em;text-transform:uppercase;color:#b9c6d2;order:2}
.hero-stats dd{margin:0;font-family:var(--display);font-weight:900;font-size:1.7rem;line-height:1.05}
.hero-stats>div{display:flex;flex-direction:column-reverse;gap:4px}

.avisos:empty{display:none}
.avisos{margin-top:18px}
.aviso{border-left:5px solid var(--amarelo);background:#fff8dc;color:var(--ink);padding:14px 16px;border-radius:0 10px 10px 0;margin:12px 0;font-size:1rem}
.aviso.erro{border-left-color:var(--lula);background:#fbecea}
.aviso strong{display:block;font-family:var(--mono);font-size:.74rem;letter-spacing:.1em;text-transform:uppercase;margin-bottom:4px}

/* manchete do hero: dois números nacionais */
.hero-manchete{display:grid;grid-template-columns:1fr;gap:18px;margin:30px 0 0;max-width:860px}
.hero-manchete:empty{display:none}
.hero-manchete>div{border-left:5px solid var(--amarelo);padding:2px 0 2px 16px}
.hero-manchete>div.m2{border-left-color:var(--verde-claro)}
.hero-manchete b{display:block;font-family:var(--display);font-weight:900;font-size:clamp(2.4rem,9vw,4.2rem);line-height:1;letter-spacing:-.02em;color:#fff}
.hero-manchete span{display:block;color:#dfe5ea;font-size:1rem;margin-top:6px;max-width:44ch}
