  av.innerHTML = '<div class="aviso erro"><strong>Aberta como arquivo local</strong>Esta página lê arquivos de dados e precisa ser aberta por um endereço da web, não direto do disco. Use https://brasil.arvor.co/politizesuavizinhanca.html, ou rode <code>python3 -m http.server 4173 --directory docs</code> e abra http://localhost:4173/politizesuavizinhanca.html.</div>';
  document.querySelectorAll('.painel button, .painel input, .painel select').forEach(function (b) { b.disabled = true; });
}
</script>
